import Foundation

// MARK: - Bearing Fruit Theme Content (20 Entries)

extension ContentLibrary {

    static let bearingFruitThemeContent: [DayContent] = [
        DayContent(
            scriptureReference: "John 15:4-5",
            scriptureText: "Remain in me, as I also remain in you. No branch can bear fruit by itself; it must remain in the vine. Neither can you bear fruit unless you remain in me. I am the vine; you are the branches. If you remain in me and I in you, you will bear much fruit; apart from me you can do nothing.",
            devotionalTitle: "Abide First, Then Bear Fruit",
            devotionalText: "Fruit doesn't come from effort — it comes from connection. A branch doesn't strain to produce grapes; it stays connected to the vine and fruit happens naturally. Your job isn't to manufacture spiritual fruit. Your job is to stay connected to Jesus. Abide in Him, and fruit will follow. Apart from Him, all your striving produces nothing.",
            prayerText: "Jesus, I abide in You. I stop striving to produce fruit on my own and start resting in my connection to You. You are the vine; I am just a branch. Keep me connected. Let fruit come naturally from our relationship, not from my effort. Apart from You, I can do nothing. In Jesus' name, amen.",
            reflectionPrompt: "Are you trying to bear fruit through effort, or through abiding in Jesus?",
            actionSteps: ["Spend 15 minutes today simply abiding — being with Jesus without an agenda", "Identify one area where you've been striving and surrender it to the vine"]
        ),
        DayContent(
            scriptureReference: "Galatians 5:22-23",
            scriptureText: "But the fruit of the Spirit is love, joy, peace, forbearance, kindness, goodness, faithfulness, gentleness and self-control. Against such things there is no law.",
            devotionalTitle: "Nine Flavors of Fruit",
            devotionalText: "The fruit of the Spirit isn't nine separate fruits — it's one fruit with nine characteristics. When the Spirit works in you, all nine show up together. Love leads to joy. Joy produces peace. Peace enables patience. They're interconnected. You don't get to pick which ones you want. The Spirit grows the whole fruit.",
            prayerText: "Holy Spirit, grow Your fruit in me — all nine characteristics. Love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. I can't produce these on my own. They come from You. Fill me and let Your fruit overflow from my life. In Jesus' name, amen.",
            reflectionPrompt: "Which fruit of the Spirit is most evident in your life? Which one needs the most growth?",
            actionSteps: ["Choose the fruit of the Spirit you struggle with most and ask the Spirit to grow it today", "At the end of the day, evaluate: where did the Spirit's fruit show up in my interactions?"]
        ),
        DayContent(
            scriptureReference: "John 15:8",
            scriptureText: "This is to my Father's glory, that you bear much fruit, showing yourselves to be my disciples.",
            devotionalTitle: "Fruit Glorifies God",
            devotionalText: "When you bear fruit, God gets the glory. Not you. The fruit in your life is evidence of His work, not your talent. A fruitful life is a walking billboard for God's goodness. When people see love, joy, and peace in you, they see the Father's handiwork. Your fruit doesn't point to you — it points to Him.",
            prayerText: "Father, let my life bear much fruit for Your glory. Not for my reputation, not for my comfort, but for Your name. Let every good thing in my life point back to You. I want to be so fruitful that people can't help but see You. Glorify Yourself through me. In Jesus' name, amen.",
            reflectionPrompt: "Does the fruit in your life point people to God or to you?",
            actionSteps: ["When someone compliments you today, redirect the glory to God", "Ask God to show you one way your fruit can bring Him glory this week"]
        ),
        DayContent(
            scriptureReference: "John 15:2",
            scriptureText: "He cuts off every branch in me that bears no fruit, while every branch that does bear fruit he prunes so that it will be even more fruitful.",
            devotionalTitle: "Pruning Hurts but Produces",
            devotionalText: "Pruning is painful. God cuts away things that hinder your fruitfulness — habits, relationships, comfort zones, even good things that aren't the best things. It feels like loss, but it's actually preparation for growth. If God is pruning you right now, take heart. He doesn't prune dead branches. He prunes the ones that are alive and growing.",
            prayerText: "Lord, I trust Your pruning shears. Even though it hurts, I know You're making me more fruitful. Cut away what needs to go. Remove what hinders growth. I surrender to Your process, trusting that the pain of pruning leads to the abundance of fruit. In Jesus' name, amen.",
            reflectionPrompt: "What is God pruning from your life right now? Can you trust His purpose in it?",
            actionSteps: ["Identify one thing God might be pruning and cooperate with Him instead of resisting", "Thank God for a past pruning that produced good fruit in your life"]
        ),
        DayContent(
            scriptureReference: "Psalm 1:1-3",
            scriptureText: "Blessed is the one who does not walk in step with the wicked... but whose delight is in the law of the Lord, and who meditates on his law day and night. That person is like a tree planted by streams of water, which yields its fruit in season.",
            devotionalTitle: "Planted by the Water",
            devotionalText: "A tree planted by streams never worries about drought. Its roots go deep into constant water. When you're rooted in God's Word — delighting in it, meditating on it — you become like that tree. Fruitfulness isn't about trying harder. It's about being planted in the right place. Put your roots in God's Word and fruit will come in season.",
            prayerText: "Lord, plant me by Your streams of living water. Root me deep in Your Word so that I yield fruit in every season. I don't want to be a shallow plant that withers. I want deep roots and lasting fruit. Help me delight in Your Word day and night. In Jesus' name, amen.",
            reflectionPrompt: "Are your roots deep in God's Word, or are they shallow and vulnerable to drought?",
            actionSteps: ["Commit to reading God's Word for 15 minutes today — plant your roots deeper", "Memorize one verse this week and meditate on it throughout the day"]
        ),
        DayContent(
            scriptureReference: "Matthew 7:16-17",
            scriptureText: "By their fruit you will recognize them. Do people pick grapes from thornbushes, or figs from thistles? Likewise, every good tree bears good fruit, but a bad tree bears bad fruit.",
            devotionalTitle: "Fruit Reveals Identity",
            devotionalText: "Jesus says fruit reveals what kind of tree you are. You can't fake fruit. A thorn bush can't produce grapes no matter how hard it tries. What comes out of your life — your words, actions, attitudes — reveals what's inside. Good fruit comes from a good heart connected to God. If you want better fruit, tend to the tree.",
            prayerText: "Lord, tend to my heart so that my fruit is good. I know that what comes out of my life reveals what's inside. Where my fruit has been sour or sparse, heal the tree. Give me a healthy heart that naturally produces good fruit. In Jesus' name, amen.",
            reflectionPrompt: "What does the fruit of your life reveal about the condition of your heart?",
            actionSteps: ["Honestly evaluate the fruit in your life this week — is it good?", "Address one heart issue that might be producing bad fruit"]
        ),
        DayContent(
            scriptureReference: "Colossians 1:10",
            scriptureText: "So that you may live a life worthy of the Lord and please him in every way: bearing fruit in every good work, growing in the knowledge of God.",
            devotionalTitle: "Fruit in Every Good Work",
            devotionalText: "Paul connects fruitfulness with knowing God. The more you know Him, the more fruit you bear. And fruit shows up in every good work — not just spiritual activities, but everyday actions. Your kindness at work is fruit. Your patience at home is fruit. Your integrity in business is fruit. Every good work done for God's glory bears eternal fruit.",
            prayerText: "Lord, help me bear fruit in every good work — at home, at work, in my community. I want to live worthy of You in every area. Grow my knowledge of You so that fruitfulness flows into everything I do. Let every good work glorify Your name. In Jesus' name, amen.",
            reflectionPrompt: "In which area of your life — work, home, relationships — do you most need to bear fruit?",
            actionSteps: ["Do one good work today specifically to bear fruit for God's kingdom", "Ask God to show you where everyday actions can become kingdom fruit"]
        ),
        DayContent(
            scriptureReference: "Matthew 13:23",
            scriptureText: "But the seed falling on good soil refers to someone who hears the word and understands it. This is the one who produces a crop, yielding a hundred, sixty or thirty times what was sown.",
            devotionalTitle: "Be Good Soil",
            devotionalText: "In the parable of the sower, the seed is the same everywhere. The difference is the soil. Hard hearts, shallow roots, and choking worries all prevent fruit. But good soil — a heart that hears, understands, and receives God's Word — produces an abundant crop. You can't control what seeds God plants. But you can tend your soil.",
            prayerText: "Lord, make my heart good soil. Remove the rocks of hardness, the shallowness of half-commitment, and the thorns of worry. I want Your Word to take deep root in me and produce an abundant harvest — thirty, sixty, a hundredfold. Prepare my soil for Your seed. In Jesus' name, amen.",
            reflectionPrompt: "What kind of soil is your heart right now? What needs to change?",
            actionSteps: ["Identify one 'thorn' (worry, distraction) that's choking God's Word in your life and remove it", "Receive one truth from Scripture today with an open, receptive heart"]
        ),
        DayContent(
            scriptureReference: "Galatians 6:9",
            scriptureText: "Let us not become weary in doing good, for at the proper time we will reap a harvest if we do not give up.",
            devotionalTitle: "Don't Give Up Before the Harvest",
            devotionalText: "Fruit takes time. Farmers don't plant in the morning and harvest by lunch. There's a season between sowing and reaping, and it requires patience. If you've been doing good and haven't seen results yet, don't give up. The harvest is coming — at the proper time, not yours. Keep sowing. Keep doing good. The fruit will come.",
            prayerText: "Lord, I'm tired of waiting for fruit. But I choose not to give up. I trust Your timing — the proper time, not mine. Renew my strength to keep sowing good seeds even when I can't see the harvest yet. I will not grow weary. I will reap. In Jesus' name, amen.",
            reflectionPrompt: "Where are you tempted to give up because you haven't seen fruit yet?",
            actionSteps: ["Keep doing one good thing you've been doing even though you haven't seen results yet", "Write 'Don't give up — harvest is coming' where you'll see it daily"]
        ),
        DayContent(
            scriptureReference: "James 3:17-18",
            scriptureText: "But the wisdom that comes from heaven is first of all pure; then peace-loving, considerate, submissive, full of mercy and good fruit, impartial and sincere. Peacemakers who sow in peace reap a harvest of righteousness.",
            devotionalTitle: "Wisdom Bears Fruit",
            devotionalText: "Heavenly wisdom isn't just smart — it's fruitful. It produces purity, peace, consideration, mercy, and sincerity. When you operate from God's wisdom, good fruit follows naturally. And notice: peacemakers reap a harvest of righteousness. The way you handle conflict, pursue peace, and show mercy directly affects your fruitfulness.",
            prayerText: "Lord, give me heavenly wisdom that bears good fruit. Make me pure, peace-loving, considerate, merciful, and sincere. I want my life to overflow with the fruit of Your wisdom. Help me sow peace today and reap a harvest of righteousness. In Jesus' name, amen.",
            reflectionPrompt: "Is the wisdom guiding your decisions producing good fruit or creating conflict?",
            actionSteps: ["Choose wisdom over cleverness in one decision today", "Sow peace in one relationship and watch for the harvest of righteousness"]
        ),
        DayContent(
            scriptureReference: "John 12:24",
            scriptureText: "Very truly I tell you, unless a kernel of wheat falls to the ground and dies, it produces only a single seed. But if it dies, it produces many seeds.",
            devotionalTitle: "Dying to Bear Fruit",
            devotionalText: "Jesus reveals a paradox: life comes through death. A seed must die to become a plant that bears much fruit. Some of your greatest fruitfulness will come from your deepest dying — dying to self, to control, to your own plans. What feels like loss is actually the beginning of multiplication. Let go, and watch what God grows.",
            prayerText: "Lord, I'm willing to die to myself so You can produce fruit through me. What I'm holding onto, I release. What I'm clinging to, I surrender. Use my letting go as the seed that produces much fruit. I trust Your paradox: through death comes life, through loss comes abundance. In Jesus' name, amen.",
            reflectionPrompt: "What are you being asked to let die so that something more fruitful can grow?",
            actionSteps: ["Surrender one thing you've been holding onto and trust God to multiply it", "Reflect on a past 'death' in your life that produced unexpected fruit"]
        ),
        DayContent(
            scriptureReference: "Philippians 1:11",
            scriptureText: "Filled with the fruit of righteousness that comes through Jesus Christ — to the glory and praise of God.",
            devotionalTitle: "Fruit of Righteousness",
            devotionalText: "The fruit Paul prays for isn't productivity or success — it's righteousness. Right living, right relationships, right character. And it comes through Jesus Christ, not through self-improvement. When you're filled with this kind of fruit, it brings glory to God. The world measures fruit by output. God measures it by righteousness.",
            prayerText: "Lord, fill me with the fruit of righteousness that comes through Jesus. Not the world's version of success, but Your version of fruitfulness. Let my life be characterized by right living, right loving, and right giving — all to Your glory and praise. In Jesus' name, amen.",
            reflectionPrompt: "By God's measure, how fruitful is your life right now?",
            actionSteps: ["Do one thing today that is righteous even if no one sees it", "Ask God to redefine success in your mind according to His standard of fruit"]
        ),
        DayContent(
            scriptureReference: "Hosea 10:12",
            scriptureText: "Sow righteousness for yourselves, reap the fruit of unfailing love, and break up your unplowed ground; for it is time to seek the Lord, until he comes and showers his righteousness on you.",
            devotionalTitle: "Break Up the Hard Ground",
            devotionalText: "Before fruit can grow, hard ground must be broken up. Unplowed ground is a heart that's become hard — through hurt, cynicism, busyness, or neglect. Hosea says break it up. Do the hard work of softening your heart. Seek the Lord. And when the soil is ready, God showers His righteousness and fruit springs up.",
            prayerText: "Lord, break up my hard ground. Where my heart has become calloused or resistant, soften it. I want to be fertile soil for Your righteousness. I seek You with all my heart. Come and shower Your righteousness on me. Prepare me for fruit. In Jesus' name, amen.",
            reflectionPrompt: "Where has your heart become hard ground that needs breaking up?",
            actionSteps: ["Identify one area of hardness in your heart and bring it to God in prayer", "Do something this week that softens your heart — serve, worship, or spend time with someone who challenges you"]
        ),
        DayContent(
            scriptureReference: "Matthew 21:43",
            scriptureText: "Therefore I tell you that the kingdom of God will be taken away from you and given to a people who will produce its fruit.",
            devotionalTitle: "God Expects Fruit",
            devotionalText: "Jesus is clear: God expects fruit. He doesn't plant and walk away hoping something grows. He expects a return on His investment. This isn't about earning God's love — it's about living into your purpose. God has invested His Spirit, His Word, His grace, and His calling in you. He expects fruit. Not perfection — fruit.",
            prayerText: "Lord, I take Your expectation of fruit seriously. You've invested so much in me — Your Spirit, Your Word, Your grace. Help me produce a return. I don't want to be a fruitless tree. I want to fulfill the purpose You've planted in me. Produce through me what You expect from me. In Jesus' name, amen.",
            reflectionPrompt: "Is your life producing the fruit God expects from the investment He's made in you?",
            actionSteps: ["Evaluate what God has invested in you and ask whether you're producing a return", "Take one action today that bears kingdom fruit — serve, share, love, or give"]
        ),
        DayContent(
            scriptureReference: "Proverbs 12:12",
            scriptureText: "The wicked desire the stronghold of evildoers, but the root of the righteous endures.",
            devotionalTitle: "Deep Roots, Lasting Fruit",
            devotionalText: "Quick results are tempting, but lasting fruit comes from deep roots. The righteous endure because their roots go deep — into God's Word, into prayer, into community. Shallow roots produce quick growth that doesn't last. Deep roots produce fruit that endures for a lifetime. Invest in your roots. The fruit will take care of itself.",
            prayerText: "Lord, deepen my roots. I don't want quick growth that doesn't last. I want the kind of deep, enduring rootedness that produces fruit for a lifetime. Ground me in Your Word, Your presence, and Your community. Let my roots go so deep that nothing can uproot me. In Jesus' name, amen.",
            reflectionPrompt: "Are your spiritual roots deep enough to sustain long-term fruitfulness?",
            actionSteps: ["Invest in one root-deepening practice today: prayer, Scripture, or community", "Evaluate whether your spiritual habits are building deep roots or just surface growth"]
        ),
        DayContent(
            scriptureReference: "Luke 8:15",
            scriptureText: "But the seed on good soil stands for those with a noble and good heart, who hear the word, retain it, and by persevering produce a crop.",
            devotionalTitle: "Perseverance Produces the Crop",
            devotionalText: "Luke adds a detail the other Gospels emphasize less: perseverance. Good soil hears and retains, but the crop comes through persevering. Fruitfulness requires sticking with it. Not giving up when growth is slow. Not abandoning the field when weeds appear. Keep going. The crop comes to those who persevere.",
            prayerText: "Lord, give me the perseverance to produce a crop. I hear Your Word and I retain it — now help me stick with it long enough to see fruit. When I want to quit, remind me that the harvest requires patience. I will persevere. In Jesus' name, amen.",
            reflectionPrompt: "Where do you need to persevere longer before you'll see fruit?",
            actionSteps: ["Recommit to one spiritual practice you've been inconsistent with", "Set a 30-day challenge: do one fruitful thing every day for a month"]
        ),
        DayContent(
            scriptureReference: "Isaiah 27:6",
            scriptureText: "In days to come Jacob will take root, Israel will bud and blossom and fill all the world with fruit.",
            devotionalTitle: "Your Fruit Can Fill the World",
            devotionalText: "God's vision for your fruitfulness isn't small. He sees your fruit filling the world. What starts as a single root becomes a bud, then a blossom, then fruit that spreads beyond anything you imagined. Don't limit what God can do through your faithfulness. Your small obedience can produce world-filling fruit in God's economy.",
            prayerText: "Lord, I dream big about the fruit You can produce through me. Take my small roots and make them bud, blossom, and fill the world. I don't limit Your vision. Use my faithfulness to produce fruit that reaches further than I can see. In Jesus' name, amen.",
            reflectionPrompt: "What would it look like if your fruit spread beyond your immediate circle?",
            actionSteps: ["Pray for your fruit to reach beyond your own community", "Plant one seed today that could produce fruit for generations"]
        ),
        DayContent(
            scriptureReference: "John 15:16",
            scriptureText: "You did not choose me, but I chose you and appointed you so that you might go and bear fruit — fruit that will last.",
            devotionalTitle: "Chosen to Bear Lasting Fruit",
            devotionalText: "Jesus chose you for a purpose: fruit that lasts. Not temporary results or fleeting impact. Lasting fruit. The kind that endures through seasons, survives storms, and multiplies over time. You weren't chosen randomly. You were appointed — hand-picked by Jesus — to produce something that will still be standing long after you're gone.",
            prayerText: "Jesus, You chose me and appointed me. That's humbling and empowering. Help me bear fruit that lasts — not temporary achievements, but eternal impact. I want to produce something that endures. Use my life for lasting fruit that glorifies You forever. In Jesus' name, amen.",
            reflectionPrompt: "What lasting fruit do you want your life to produce?",
            actionSteps: ["Identify one thing you can invest in today that will produce lasting, not temporary, fruit", "Write down the lasting fruit you want your life to be known for"]
        ),
        DayContent(
            scriptureReference: "Ezekiel 47:12",
            scriptureText: "Fruit trees of all kinds will grow on both banks of the river. Their leaves will not wither, nor will their fruit fail. Every month they will bear fruit, because the water from the sanctuary flows to them.",
            devotionalTitle: "Fruit Every Month",
            devotionalText: "Ezekiel's vision shows trees that bear fruit every month — not just in one season. The secret? They're planted by the river flowing from God's sanctuary. When your life is fed by God's presence, fruitfulness isn't seasonal. You bear fruit constantly because the water never stops flowing. Stay close to the source.",
            prayerText: "Lord, let me be like the trees in Ezekiel's vision — bearing fruit every month because I'm planted by Your river. Keep me close to Your presence, the source of constant fruitfulness. Let my leaves never wither and my fruit never fail. Flow through me, Lord. In Jesus' name, amen.",
            reflectionPrompt: "Is your fruitfulness seasonal or constant? What would it take to bear fruit every month?",
            actionSteps: ["Position yourself closer to God's presence today — pray, worship, or read His Word", "Evaluate: am I drawing from the source consistently, or only when I'm desperate?"]
        ),
        DayContent(
            scriptureReference: "Revelation 22:2",
            scriptureText: "On each side of the river stood the tree of life, bearing twelve crops of fruit, yielding its fruit every month. And the leaves of the tree were for the healing of the nations.",
            devotionalTitle: "Fruit That Heals",
            devotionalText: "In God's ultimate vision, the tree of life bears fruit that heals nations. Your fruitfulness isn't just for your benefit — it's for the healing of others. Every act of love, every word of truth, every moment of faithfulness contributes to the healing of the people around you. Your fruit has healing power. Bear it generously.",
            prayerText: "Lord, let my fruit bring healing. Not just to me, but to the people and places around me. Use the love, joy, peace, and faithfulness in my life to heal broken hearts, broken relationships, and broken communities. My fruit is for others. Help me bear it generously. In Jesus' name, amen.",
            reflectionPrompt: "Whose life might be healed by the fruit God is producing in you?",
            actionSteps: ["Offer the fruit of your life to someone who needs healing today — a kind word, a listening ear, a helping hand", "Pray for the nations and believe that your faithfulness contributes to God's healing work in the world"]
        ),
    ]
}
